import sys

def totalNQueens(n):
    res = 0
    cols = [False] * n
    diag1 = [False] * (2 * n - 1)
    diag2 = [False] * (2 * n - 1)
    def backtrack(row):
        nonlocal res
        if row == n:
            res += 1
            return
        for col in range(n):
            if not (cols[col] or diag1[row + col] or diag2[row - col + n - 1]):
                cols[col] = diag1[row + col] = diag2[row - col + n - 1] = True
                backtrack(row + 1)
                cols[col] = diag1[row + col] = diag2[row - col + n - 1] = False
    backtrack(0)
    return res

if __name__ == '__main__':
    content = sys.stdin.read().strip()
    if content:
        n = int(content)
        print(totalNQueens(n))

